### 2. User-Level Tools (C Source Code)

These programs fulfill Requirements 2.2, 2.3, and 2.4.

#### `user/directoryWalker.c`
```c
#include "kernel/types.h"
#include "kernel/stat.h"
#include "user/user.h"

void walk(char *path) {
  int fd;
  struct stat st;
  struct dirent de;
  char buf[512], *p;

  if((fd = open(path, 0)) < 0) return;
  if(fstat(fd, &st) < 0 || st.type != T_DIR) {
    close(fd);
    return;
  }

  while(read(fd, &de, sizeof(de)) == sizeof(de)) {
    if(de.inum == 0 || strcmp(de.name, ".") == 0 || strcmp(de.name, "..") == 0)
      continue;
    printf("Found: %s/%s (Inode %d)\n", path, de.name, de.inum);

    strcpy(buf, path);
    p = buf + strlen(buf);
    *p++ = '/';
    memcpy(p, de.name, DIRSIZ);
    p[DIRSIZ] = 0;
    walk(buf);
  }
  close(fd);
}

int main() {
  walk("");
  exit(0);
}
```

#### `user/imapWalker.c`
```c
#include "kernel/types.h"
#include "kernel/fs.h"
#include "user/user.h"

int main() {
    struct inode_info info;
    printf("Inum | Type | Size | Links\n");
    // Standard xv6 NINODES is 200; imapwalker iterates through the entire range
    for(int i = 1; i < 200; i++) {
        if(get_dinode(i, &info) == 0 && info.type != 0) {
            printf("%d    | %d    | %d  | %d\n", i, info.type, info.size, info.nlink);
        }
    }
    exit(0);
}
```

#### `user/inodeReader.c`
```c
#include "kernel/types.h"
#include "kernel/fs.h"
#include "user/user.h"

int main(int argc, char *argv[]) {
    if(argc < 2) { printf("Usage: inodereader inum\n"); exit(1); }
    struct inode_info info;
    int inum = atoi(argv[1]);
    if(get_dinode(inum, &info) < 0) { printf("Error reading inode\n"); exit(1); }
    printf("Inode: %d\nType: %d\nSize: %d\nLinks: %d\nBlocks: ", inum, info.type, info.size, info.nlink);
    for(int i=0; i<13; i++) printf("%d ", info.addrs[i]);
    printf("\n");
    exit(0);
}
```

