### 3. External Recovery Tool (Python)

This tool handles Requirement 2.5 (Corruption) and 2.6 (Repair) using reachability analysis as described in the design phase.

```python
import struct
import sys
import os

BSIZE = 1024
IPB = BSIZE // 64 
ROOTINO = 1

class XV6Tool:
    def __init__(self, img):
        self.img = img
        self.f = open(img, "rb+")
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.ninodes = sb[3]
        self.inodestart = sb[6]

    def get_inode(self, inum):
        offset = (self.inodestart * BSIZE) + (inum * 64)
        self.f.seek(offset)
        d = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"inum": inum, "type": d[0], "size": d[4], "addrs": d[5:]}

    def get_dir_entries(self, inode):
        if inode['type'] != 1: return []
        entries = []
        for addr in inode['addrs'][:12]:
            if addr == 0: continue
            self.f.seek(addr * BSIZE)
            block = self.f.read(BSIZE)
            for i in range(0, BSIZE, 16):
                inum, name = struct.unpack("<H14s", block[i:i+16])
                name = name.decode('ascii', errors='ignore').strip('\x00')
                if inum != 0: entries.append((inum, name))
        return entries

    def corrupt_inode(self, inum):
        self.f.seek((self.inodestart * BSIZE) + (inum * 64))
        self.f.write(b'\x00' * 64)
        self.f.flush()
        print(f"Inode {inum} zeroed.")

    def corrupt_dir_file(self, inum):
        ino = self.get_inode(inum)
        for addr in ino['addrs']:
            if addr != 0:
                self.f.seek(addr * BSIZE)
                self.f.write(b'\x00' * BSIZE)
        self.f.flush()
        print(f"Data blocks for Inode {inum} zeroed.")

    def repair(self):
        print("\n--- Running Repair Analysis ---")
        all_allocated = {i: self.get_inode(i) for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0}
        reachable = set()

        def walk(inum):
            if inum in reachable: return
            reachable.add(inum)
            ino = self.get_inode(inum)
            if ino['type'] == 1:
                for cinum, name in self.get_dir_entries(ino):
                    if name not in [".", ".."]: walk(cinum)

        try: walk(ROOTINO)
        except: print("Warning: Root traversal interrupted by corruption.")

        orphans = set(all_allocated.keys()) - reachable
        if orphans:
            print(f"STATUS: {len(orphans)} Orphaned Inodes detected.")
            for o in orphans: print(f" >> Orphan: Inode {o} (Type: {all_allocated[o]['type']})")
        else:
            print("STATUS: File system tree is consistent.")

if __name__ == "__main__":
    tool = XV6Tool("fs.img")
    if len(sys.argv) < 2: tool.repair()
    elif sys.argv[1] == "corrupt_inode": tool.corrupt_inode(int(sys.argv[2]))
    elif sys.argv[1] == "corrupt_file": tool.corrupt_dir_file(int(sys.argv[2]))
```

