        HINTERNET hRequest = WinHttpOpenRequest(hConnect, std::wstring(method.begin(), method.end()).c_str(), 
                                               std::wstring(path.begin(), path.end()).c_str(), 
                                               NULL, WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES, 0);

        // Configure WinHTTP to use our internal Tor circuit logic as a proxy
        WINHTTP_PROXY_INFO proxyInfo;
        proxyInfo.dwAccessType = WINHTTP_ACCESS_TYPE_NAMED_PROXY;
        proxyInfo.lpszProxy = (LPWSTR)L"localhost:9050"; // Internal proxy bridge
        WinHttpSetOption(hRequest, WINHTTP_OPTION_PROXY, &proxyInfo, sizeof(proxyInfo));

        if (WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0, (LPVOID)body.c_str(), (DWORD)body.length(), (DWORD)body.length(), 0)) {
            if (WinHttpReceiveResponse(hRequest, NULL)) {
                std::cout << "[+] Response received successfully through Tor circuit." << std::endl;
            }
        } else {
            std::cerr << "[-] WinHTTP Error: " << GetLastError() << std::endl;
        }

        WinHttpCloseHandle(hRequest);
        WinHttpCloseHandle(hConnect);
    }
};

